C · adjacency lists · iteration · L3
Concept: Mark a vertex visited when it is pushed on the queue, not when it is popped
Misconception: It is enough to mark a vertex visited when it is dequeued.
Explanation: If the mark is set only on dequeue, a vertex that is reachable from two queued vertices is pushed twice. The queue then grows beyond n entries, and a queue array of n entries overflows. Marking on enqueue guarantees each vertex enters the queue once, so n slots are enough. BFS over a list takes O(V + E).
Incorrect (undefined behaviour reported by the sanitizer: heap-buffer-overflow):
size_t alBfsBad(const AdjList *l, size_t start, int *order) {
  int *queue = malloc(l->n * sizeof *queue);
  unsigned char *seen = calloc(l->n, 1);
  size_t head = 0, tail = 0, count = 0;
  queue[tail++] = (int)start;
  while (head < tail) {
    int u = queue[head++];
    if (seen[u]) continue;
    seen[u] = 1;
    order[count++] = u;
    for (const AdjEdge *e = l->head[u]; e != NULL; e = e->next)
      if (!seen[e->to]) queue[tail++] = e->to;
  }
  free(queue);
  free(seen);
  return count;
}
Correct:
size_t alBfs(const AdjList *l, size_t start, int *order) {
  if (start >= l->n) return 0;
  int *queue = malloc(l->n * sizeof *queue);
  unsigned char *seen = calloc(l->n, 1);
  size_t head = 0, tail = 0, count = 0;
  if (queue == NULL || seen == NULL) { free(queue); free(seen); return 0; }
  queue[tail++] = (int)start;
  seen[start] = 1;
  while (head < tail) {
    int u = queue[head++];
    order[count++] = u;
    for (const AdjEdge *e = l->head[u]; e != NULL; e = e->next)
      if (!seen[e->to]) { seen[e->to] = 1; queue[tail++] = e->to; }
  }
  free(queue);
  free(seen);
  return count;
}
Complexity: O(V + E)

