C · AVL trees · insertion-and-deletion · L3
Concept: Deletion also rebalances every node on the path, because removing a node can shorten one side
Misconception: Deletion only needs the BST logic; balance is restored by the next insertion.
Explanation: Removing a node can make the other side too tall, with an imbalance of 2 at some ancestor. Delete as in a BST (copy the successor when there are two children), then rebalance each ancestor on the return path. Skipping it leaves a tree that is no longer AVL, and later operations lose the logarithmic bound.
Incorrect:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
ANode *avlDeleteBad(ANode *t, int key) {
  if (t == NULL) return NULL;
  if (key < t->key) {
    t->l = avlDeleteBad(t->l, key);
  } else if (key > t->key) {
    t->r = avlDeleteBad(t->r, key);
  } else {
    if (t->l == NULL) { ANode *r = t->r; free(t); return r; }
    if (t->r == NULL) { ANode *l = t->l; free(t); return l; }
    ANode *m = t->r;
    while (m->l != NULL) m = m->l;
    t->key = m->key;
    t->r = avlDeleteBad(t->r, m->key);
  }
  return t;
}
Correct:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
ANode *avlDelete(ANode *t, int key) {
  if (t == NULL) return NULL;
  if (key < t->key) {
    t->l = avlDelete(t->l, key);
  } else if (key > t->key) {
    t->r = avlDelete(t->r, key);
  } else {
    if (t->l == NULL) { ANode *r = t->r; free(t); return r; }
    if (t->r == NULL) { ANode *l = t->l; free(t); return l; }
    ANode *m = t->r;
    while (m->l != NULL) m = m->l;
    t->key = m->key;
    t->r = avlDelete(t->r, m->key);
  }
  return rebalance(t);
}
Complexity: O(log n)

