C · binary trees · iteration · L3
Concept: Use an explicit stack for inorder traversal of deep trees; recursion overflows the call stack
Misconception: Recursive traversal is fine for any tree.
Explanation: Every recursive call uses stack memory, so the recursion depth equals the tree height. A degenerate tree with 200000 nodes in a chain overflows the default 8 MB stack. An explicit stack on the heap holds the pending ancestors: go left as far as possible, pop to visit, then go right.
Incorrect (undefined behaviour reported by the sanitizer: stack-overflow):
typedef struct TNode { int val; struct TNode *left, *right; } TNode;
TNode *newNode(int v) {
  TNode *t = malloc(sizeof *t);
  if (t == NULL) return NULL;
  t->val = v;
  t->left = t->right = NULL;
  return t;
}
void inorderRec(const TNode *t, int *out, size_t *n) {
  if (t == NULL) return;
  inorderRec(t->left, out, n);
  out[(*n)++] = t->val;
  inorderRec(t->right, out, n);
}
Correct:
typedef struct TNode { int val; struct TNode *left, *right; } TNode;
size_t inorderIter(const TNode *root, size_t maxDepth, int *out) {
  const TNode **st = malloc(maxDepth * sizeof *st);
  if (st == NULL) return 0;
  size_t top = 0, n = 0;
  const TNode *cur = root;
  while (cur != NULL || top > 0) {
    while (cur != NULL) {
      st[top++] = cur;
      cur = cur->left;
    }
    cur = st[--top];
    out[n++] = cur->val;
    cur = cur->right;
  }
  free(st);
  return n;
}
Complexity: O(n)

