C · binary search trees · patterns · L3
Concept: Count a key range by pruning subtrees that cannot contain keys in it
Misconception: Counting keys in a range requires visiting every node.
Explanation: If a node's key is not greater than the lower bound, nothing in its left subtree can be in range, and if it is not less than the upper bound, nothing in the right subtree can. Skipping those subtrees makes the cost O(height + k) for k results instead of O(n).
Incorrect:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
size_t rangeCountBad(const BNode *t, int lo, int hi, size_t *visited) {
  if (t == NULL) return 0;
  (*visited)++;
  size_t c = (t->key >= lo && t->key <= hi);
  c += rangeCountBad(t->left, lo, hi, visited);
  return c + rangeCountBad(t->right, lo, hi, visited);
}
Correct:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
size_t rangeCount(const BNode *t, int lo, int hi, size_t *visited) {
  if (t == NULL) return 0;
  (*visited)++;
  size_t c = (t->key >= lo && t->key <= hi);
  if (t->key > lo) c += rangeCount(t->left, lo, hi, visited);
  if (t->key < hi) c += rangeCount(t->right, lo, hi, visited);
  return c;
}
Complexity: O(h + k)

