C · binary search trees · access · L1
Concept: A search must stop at NULL: the key may be absent
Misconception: Descending by comparison always ends at the key.
Explanation: Each comparison discards one subtree, so a search costs O(height). If the key is missing the walk reaches a NULL link, which is the not-found answer. A loop that only tests the key dereferences NULL for absent keys. The leftmost node is the minimum, and an inorder walk lists the keys in sorted order.
Incorrect (undefined behaviour reported by the sanitizer: null pointer):
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
int bstContainsBad(const BNode *t, int key) {
  while (t->key != key) t = key < t->key ? t->left : t->right;
  return 1;
}
Correct:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
int bstContains(const BNode *t, int key) {
  while (t != NULL) {
    if (key == t->key) return 1;
    t = key < t->key ? t->left : t->right;
  }
  return 0;
}
const BNode *bstMin(const BNode *t) {
  while (t != NULL && t->left != NULL) t = t->left;
  return t;
}
void bstInorder(const BNode *t, int *out, size_t *n) {
  if (t == NULL) return;
  bstInorder(t->left, out, n);
  out[(*n)++] = t->key;
  bstInorder(t->right, out, n);
}
Complexity: O(h)

