C · B-trees and B+ trees · creation · L3
Concept: Insert top-down and split every full node on the way, so a leaf always has room for the new key
Misconception: Insert into the leaf and deal with overflow afterwards.
Explanation: A node has room for only three keys. Writing a fourth key overruns the array. The top-down method splits each full node it meets while descending, so by the time it reaches a leaf there is space. A full root is split first and a new root is created, which increases the height by one. Duplicates are checked before inserting.
Incorrect (undefined behaviour reported by the sanitizer: out of bounds):
typedef struct BT { int n, leaf; int keys[3]; struct BT *c[4]; } BT;
void btInsertLeafBad(BT *x, int k) {
  int i = x->n - 1;
  while (i >= 0 && k < x->keys[i]) {
    x->keys[i + 1] = x->keys[i];
    i--;
  }
  x->keys[i + 1] = k;
  x->n++;
}
Correct:
typedef struct BT { int n, leaf; int keys[3]; struct BT *c[4]; } BT;
BT *btNew(int leaf) {
  BT *x = calloc(1, sizeof *x);
  if (x != NULL) x->leaf = leaf;
  return x;
}
void btInsertNonFull(BT *x, int k) {
  int i = x->n - 1;
  if (x->leaf) {
    while (i >= 0 && k < x->keys[i]) {
      x->keys[i + 1] = x->keys[i];
      i--;
    }
    x->keys[i + 1] = k;
    x->n++;
    return;
  }
  while (i >= 0 && k < x->keys[i]) i--;
  i++;
  if (x->c[i]->n == 3) {
    BT *z = btNew(x->c[i]->leaf);
    if (z == NULL) return;
    btSplit(x, i, x->c[i], z);
    if (k > x->keys[i]) i++;
  }
  btInsertNonFull(x->c[i], k);
}
BT *btInsert(BT *root, int k) {
  if (root == NULL) root = btNew(1);
  if (root == NULL || btContains(root, k)) return root;
  if (root->n == 3) {
    BT *s = btNew(0), *z = btNew(root->leaf);
    if (s == NULL || z == NULL) { free(s); free(z); return root; }
    s->c[0] = root;
    btSplit(s, 0, root, z);
    root = s;
  }
  btInsertNonFull(root, k);
  return root;
}
int btHeight(const BT *x) {
  int h = 1;
  while (x != NULL && !x->leaf) { x = x->c[0]; h++; }
  return h;
}
void btFree(BT *x) {
  if (x == NULL) return;
  if (!x->leaf)
    for (int i = 0; i <= x->n; i++) btFree(x->c[i]);
  free(x);
}
Complexity: O(log n)

