C · circular linked lists · creation · L2
Concept: Keep a pointer to the tail of a circular list: tail->next is the head, so both ends are O(1)
Misconception: A circular list ends with a NULL next pointer like any other list.
Explanation: In a circular list the last node points back to the first. Storing the tail instead of the head makes both ends available: the head is tail->next. A single node points to itself, and the empty list is a NULL tail. Setting next to NULL when appending breaks the circle.
Incorrect:
typedef struct CNode { int val; struct CNode *next; } CNode;
void cllLinkBad(CNode **tail, CNode *n) {
  n->next = NULL;
  if (*tail != NULL) (*tail)->next = n;
  *tail = n;
}
Correct:
typedef struct CNode { int val; struct CNode *next; } CNode;
int cllPushBack(CNode **tail, int v) {
  CNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  n->val = v;
  if (*tail == NULL) {
    n->next = n;
  } else {
    n->next = (*tail)->next;
    (*tail)->next = n;
  }
  *tail = n;
  return 1;
}
void cllFree(CNode *tail) {
  if (tail == NULL) return;
  CNode *p = tail->next;
  tail->next = NULL;
  while (p != NULL) {
    CNode *next = p->next;
    free(p);
    p = next;
  }
}
Complexity: O(1)

