typedef struct { DNode *head, *tail; size_t len; } DList;
void dlLinkAfterBad(DNode *pos, DNode *n) {
  n->prev = pos;
  pos->next = n;
  n->next = pos->next;
}
Correct:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
int dlInsertAfter(DList *l, DNode *pos, int v) {
  DNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  n->val = v;
  n->prev = pos;
  n->next = pos->next;
  if (pos->next != NULL) pos->next->prev = n; else l->tail = n;
  pos->next = n;
  l->len++;
  return 1;
}
Complexity: O(1)

