C · doubly linked lists · patterns · L3
Concept: Move a node to the front in O(1): unlink it, fix the tail if needed, then relink at the head (LRU caches)
Misconception: Relinking at the head is enough; the old position can be left as is.
Explanation: An LRU cache keeps a doubly linked list ordered by recency and moves a touched entry to the front. The node must be unlinked first, including updating the tail when it was last; otherwise the list contains it twice or the tail points to the front node.
Incorrect:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
void dlMoveToFrontBad(DList *l, DNode *n) {
  if (n == l->head) return;
  n->prev->next = n->next;
  if (n->next != NULL) n->next->prev = n->prev;
  n->prev = NULL;
  n->next = l->head;
  l->head->prev = n;
  l->head = n;
}
Correct:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
void dlMoveToFront(DList *l, DNode *n) {
  if (n == l->head) return;
  n->prev->next = n->next;
  if (n->next != NULL) n->next->prev = n->prev; else l->tail = n->prev;
  n->prev = NULL;
  n->next = l->head;
  l->head->prev = n;
  l->head = n;
}
Complexity: O(1)

