C · dynamic arrays · insertion-and-deletion · L2
Concept: Insert in the middle by shifting the tail right with memmove, last element first
Misconception: Copy elements forward one slot at a time to open a gap.
Explanation: Shifting right with a forward loop copies each element over the next one before it is moved, so one value is repeated. Use memmove, which handles overlapping ranges, or loop from the end. Reserve capacity first; inserting is O(n) because every later element moves.
Incorrect:
typedef struct { int *data; size_t len, cap; } Vec;
void vecInsertBad(Vec *v, size_t i, int x) {
  for (size_t j = i; j < v->len; j++) v->data[j + 1] = v->data[j];
  v->data[i] = x;
  v->len++;
}
Correct:
typedef struct { int *data; size_t len, cap; } Vec;
int vecReserve(Vec *v, size_t need) {
  if (need <= v->cap) return 1;
  size_t nc = v->cap != 0 ? v->cap : 4;
  while (nc < need) nc *= 2;
  int *p = realloc(v->data, nc * sizeof *p);
  if (p == NULL) return 0;
  v->data = p;
  v->cap = nc;
  return 1;
}
int vecPush(Vec *v, int x) {
  if (!vecReserve(v, v->len + 1)) return 0;
  v->data[v->len++] = x;
  return 1;
}
int vecInsert(Vec *v, size_t i, int x) {
  if (i > v->len || !vecReserve(v, v->len + 1)) return 0;
  memmove(&v->data[i + 1], &v->data[i], (v->len - i) * sizeof *v->data);
  v->data[i] = x;
  v->len++;
  return 1;
}
void vecFree(Vec *v) {
  free(v->data);
  v->data = NULL;
  v->len = v->cap = 0;
}
Complexity: O(n)

