C · hash sets · insertion-and-deletion · L1
Concept: A set stores each value once: check membership before inserting
Misconception: Adding the same value twice stores it twice.
Explanation: The point of a set is uniqueness. Add must test membership and report whether the value was new. Always inserting makes the count wrong and every later operation walk longer chains.
Incorrect:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsAddBad(HSet *s, int key) {
  SNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  size_t i = hashInt(key) % s->nb;
  n->key = key;
  n->next = s->b[i];
  s->b[i] = n;
  s->count++;
  return 1;
}
Correct:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsAddNew(HSet *s, int key) {
  for (const SNode *n = s->b[hashInt(key) % s->nb]; n != NULL; n = n->next)
    if (n->key == key) return 0;
  SNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  size_t i = hashInt(key) % s->nb;
  n->key = key;
  n->next = s->b[i];
  s->b[i] = n;
  s->count++;
  return 1;
}
Complexity: O(1) average

