C · hash sets · access · L2
Concept: Compute the bucket from an unsigned hash; key % n is negative for negative keys
Misconception: key % nb is always a valid bucket index.
Explanation: In C the remainder takes the sign of the dividend, so -3 % 8 is -3. Using it as an array index reads before the array. Convert the key to an unsigned hash first (and mix its bits so that patterned keys spread out), then take the remainder: hashInt(key) % nb is always in 0..nb-1.
Incorrect (undefined behaviour reported by the sanitizer: heap-buffer-overflow):
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsContainsBad(const HSet *s, int key) {
  int i = key % (int)s->nb;
  for (const SNode *n = s->b[i]; n != NULL; n = n->next)
    if (n->key == key) return 1;
  return 0;
}
Correct:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsInit(HSet *s, size_t nb) {
  s->b = calloc(nb, sizeof *s->b);
  s->nb = s->b != NULL ? nb : 0;
  s->count = 0;
  return s->b != NULL;
}
int hsContains(const HSet *s, int key) {
  for (const SNode *n = s->b[hashInt(key) % s->nb]; n != NULL; n = n->next)
    if (n->key == key) return 1;
  return 0;
}
int hsAdd(HSet *s, int key) {
  if (hsContains(s, key)) return 0;
  SNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  size_t i = hashInt(key) % s->nb;
  n->key = key;
  n->next = s->b[i];
  s->b[i] = n;
  s->count++;
  return 1;
}
void hsFree(HSet *s) {
  for (size_t i = 0; i < s->nb; i++) {
    SNode *n = s->b[i];
    while (n != NULL) {
      SNode *next = n->next;
      free(n);
      n = next;
    }
  }
  free(s->b);
  s->b = NULL;
  s->nb = s->count = 0;
}
Complexity: O(1) average

