C · hash sets · insertion-and-deletion · L3
Concept: Remove an element by unlinking its node from the chain before freeing it
Misconception: Free the node you find; the chain will fix itself.
Explanation: The previous node or the bucket head still points at the freed node. Walk with an SNode ** cursor, store node->next into the link, then free. Decrement the count only when something was removed.
Incorrect (undefined behaviour reported by the sanitizer: heap-use-after-free):
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsRemoveBad(HSet *s, int key) {
  for (SNode *n = s->b[hashInt(key) % s->nb]; n != NULL; n = n->next) {
    if (n->key == key) {
      free(n);
      s->count--;
      return 1;
    }
  }
  return 0;
}
Correct:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsRemove(HSet *s, int key) {
  SNode **pp = &s->b[hashInt(key) % s->nb];
  for (; *pp != NULL; pp = &(*pp)->next) {
    if ((*pp)->key == key) {
      SNode *dead = *pp;
      *pp = dead->next;
      free(dead);
      s->count--;
      return 1;
    }
  }
  return 0;
}
Complexity: O(1) average

