C · hash tables · fit-and-alternatives · L3
Concept: With open addressing, deleting must leave a tombstone so later keys in the probe chain stay reachable
Misconception: Deleting a key from a linear-probing table just empties its slot.
Explanation: Open addressing stores entries in the array itself and probes to the next slot on a collision. Lookup stops at the first empty slot, so emptying a deleted slot cuts the probe chain and hides every key that was inserted after it. Mark the slot as a tombstone: lookups continue past it, insertions may reuse it.
Incorrect:
typedef struct { int key, val; unsigned char state; } Slot;
typedef struct { Slot *slots; size_t cap, count; } OA;
int oaDelBad(OA *t, int key) {
  size_t i = (size_t)key % t->cap;
  for (size_t n = 0; n < t->cap && t->slots[i].state != 0; n++, i = (i + 1) % t->cap)
    if (t->slots[i].state == 1 && t->slots[i].key == key) {
      t->slots[i].state = 0;
      t->count--;
      return 1;
    }
  return 0;
}
Correct:
typedef struct { int key, val; unsigned char state; } Slot;
typedef struct { Slot *slots; size_t cap, count; } OA;
int oaInit(OA *t, size_t cap) {
  t->slots = calloc(cap, sizeof *t->slots);
  t->cap = t->slots != NULL ? cap : 0;
  t->count = 0;
  return t->slots != NULL;
}
int oaPut(OA *t, int key, int val) {
  if (t->count + 1 >= t->cap) return 0;
  size_t i = (size_t)key % t->cap;
  while (t->slots[i].state == 1 && t->slots[i].key != key) i = (i + 1) % t->cap;
  if (t->slots[i].state != 1) t->count++;
  t->slots[i].key = key;
  t->slots[i].val = val;
  t->slots[i].state = 1;
  return 1;
}
int oaGet(const OA *t, int key, int *out) {
  size_t i = (size_t)key % t->cap;
  for (size_t n = 0; n < t->cap && t->slots[i].state != 0; n++, i = (i + 1) % t->cap)
    if (t->slots[i].state == 1 && t->slots[i].key == key) {
      *out = t->slots[i].val;
      return 1;
    }
  return 0;
}
int oaDel(OA *t, int key) {
  size_t i = (size_t)key % t->cap;
  for (size_t n = 0; n < t->cap && t->slots[i].state != 0; n++, i = (i + 1) % t->cap)
    if (t->slots[i].state == 1 && t->slots[i].key == key) {
      t->slots[i].state = 2;
      t->count--;
      return 1;
    }
  return 0;
}
void oaFree(OA *t) {
  free(t->slots);
  t->slots = NULL;
  t->cap = t->count = 0;
}
Complexity: O(1) average

