C · hash tables · complexity · L3
Concept: Resize by re-hashing every entry; copying the bucket array leaves entries in buckets the lookup no longer visits
Misconception: Growing the bucket array with realloc keeps all entries findable.
Explanation: The bucket index is hash % nb, so changing nb changes where every key belongs. Keep the load factor (count / nb) below about 0.75 by building a larger array and relinking each entry into its new bucket, which costs O(n) occasionally and keeps put and get O(1) on average. A plain realloc leaves the entries in their old buckets and lookups miss them.
Incorrect:
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
int tableResizeBad(Table *t, size_t nnb) {
  Entry **b = realloc(t->buckets, nnb * sizeof *b);
  if (b == NULL) return 0;
  for (size_t i = t->nb; i < nnb; i++) b[i] = NULL;
  t->buckets = b;
  t->nb = nnb;
  return 1;
}
Correct:
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
int tableResize(Table *t, size_t nnb) {
  Entry **b = calloc(nnb, sizeof *b);
  if (b == NULL) return 0;
  for (size_t i = 0; i < t->nb; i++) {
    Entry *e = t->buckets[i];
    while (e != NULL) {
      Entry *next = e->next;
      size_t j = hashStr(e->key) % nnb;
      e->next = b[j];
      b[j] = e;
      e = next;
    }
  }
  free(t->buckets);
  t->buckets = b;
  t->nb = nnb;
  return 1;
}
Complexity: O(n)

