C · priority queues · ordering · L2
Concept: A priority queue takes its ordering from a comparison function; compare long long keys without truncating the difference
Misconception: A comparison written as (int)(a - b) < 0 is safe for any long long keys.
Explanation: A priority queue stores items in a binary heap and asks a LessFn pointer which of two items comes first, so the same code serves min and max queues and composite keys. The comparison must not subtract and cast: the difference of two long long values can exceed the range of int, and the conversion wraps, so two different keys can compare as equal. Compare with < instead. push and pop are O(log n).
Incorrect:
typedef struct { long long key; int seq; int id; } Item;
int itemLessBad(const Item *a, const Item *b) {
  return (int)(a->key - b->key) < 0;
}
Correct:
typedef struct { long long key; int seq; int id; } Item;
typedef int (*LessFn)(const Item *, const Item *);
typedef struct { Item *a; size_t n, cap; LessFn less; int nextSeq; } PQ;
int itemLess(const Item *a, const Item *b) {
  if (a->key != b->key) return a->key < b->key;
  return a->seq < b->seq;
}
int itemLessKeyOnly(const Item *a, const Item *b) { return a->key < b->key; }
void pqInit(PQ *q, LessFn less) {
  q->a = NULL; q->n = q->cap = 0; q->less = less; q->nextSeq = 0;
}
int pqPush(PQ *q, long long key, int id) {
  if (q->n == q->cap) {
    size_t nc = q->cap != 0 ? q->cap * 2 : 4;
    Item *p = realloc(q->a, nc * sizeof *p);
    if (p == NULL) return 0;
    q->a = p;
    q->cap = nc;
  }
  Item it = { key, q->nextSeq++, id };
  size_t i = q->n++;
  q->a[i] = it;
  while (i > 0) {
    size_t p = (i - 1) / 2;
    if (!q->less(&q->a[i], &q->a[p])) break;
    Item t = q->a[p]; q->a[p] = q->a[i]; q->a[i] = t;
    i = p;
  }
  return 1;
}
int pqPop(PQ *q, Item *out) {
  if (q->n == 0) return 0;
  *out = q->a[0];
  q->a[0] = q->a[--q->n];
  size_t i = 0;
  for (;;) {
    size_t l = 2 * i + 1, r = l + 1, m = i;
    if (l < q->n && q->less(&q->a[l], &q->a[m])) m = l;
    if (r < q->n && q->less(&q->a[r], &q->a[m])) m = r;
    if (m == i) break;
    Item t = q->a[m]; q->a[m] = q->a[i]; q->a[i] = t;
    i = m;
  }
  return 1;
}
void pqFree(PQ *q) { free(q->a); q->a = NULL; q->n = q->cap = 0; }
Complexity: O(log n)

