C · queues · insertion-and-deletion · L1
Concept: In a circular buffer the tail slot is (head + len) % cap; without the modulo the write runs off the array
Misconception: The next free slot is data[head + len].
Explanation: A ring buffer reuses the space freed at the front. The index of the next free slot wraps around: (head + len) % cap. After some dequeues head is greater than zero, and data[head + len] can be past the end of the allocation. Report a full queue instead of overwriting.
Incorrect (undefined behaviour reported by the sanitizer: heap-buffer-overflow):
typedef struct { int *data; size_t head, len, cap; } Queue;
int queueInitBad(Queue *q, size_t cap) {
  q->data = malloc(cap * sizeof *q->data);
  q->head = q->len = 0;
  q->cap = q->data != NULL ? cap : 0;
  return q->data != NULL;
}
void enqueueBad(Queue *q, int v) {
  q->data[q->head + q->len] = v;
  q->len++;
}
Correct:
typedef struct { int *data; size_t head, len, cap; } Queue;
int queueInit(Queue *q, size_t cap) {
  q->data = malloc(cap * sizeof *q->data);
  q->head = q->len = 0;
  q->cap = q->data != NULL ? cap : 0;
  return q->data != NULL;
}
int enqueue(Queue *q, int v) {
  if (q->len == q->cap) return 0;
  q->data[(q->head + q->len) % q->cap] = v;
  q->len++;
  return 1;
}
void queueFree(Queue *q) {
  free(q->data);
  q->data = NULL;
  q->head = q->len = q->cap = 0;
}
Complexity: O(1)

