C · red-black trees · creation · L3
Concept: Insert as a red leaf, then fix the path: rotate left, rotate right, and flip colors when both children are red
Misconception: Rotations alone restore the invariants after an insertion.
Explanation: A new node is red. On the way back up three local rules fix violations: a red right child with a black left child rotates left, two reds in a row on the left rotate right, and two red children are flipped to black while their parent turns red, which pushes the problem up. Without the color flip the tree breaks the no-adjacent-red rule. The root is made black at the end.
Incorrect:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
RNode *rbInsertBad(RNode *h, int key) {
  if (h == NULL) return rbNew(key);
  if (key < h->key) h->l = rbInsertBad(h->l, key);
  else if (key > h->key) h->r = rbInsertBad(h->r, key);
  if (isRed(h->r) && !isRed(h->l)) h = rotateLeft(h);
  if (isRed(h->l) && isRed(h->l->l)) h = rotateRight(h);
  return h;
}
Correct:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
RNode *rbInsertStep(RNode *h, int key) {
  if (h == NULL) return rbNew(key);
  if (key < h->key) h->l = rbInsertStep(h->l, key);
  else if (key > h->key) h->r = rbInsertStep(h->r, key);
  if (isRed(h->r) && !isRed(h->l)) h = rotateLeft(h);
  if (isRed(h->l) && isRed(h->l->l)) h = rotateRight(h);
  if (isRed(h->l) && isRed(h->r)) flipColors(h);
  return h;
}
RNode *rbInsert(RNode *t, int key) {
  t = rbInsertStep(t, key);
  if (t != NULL) t->red = 0;
  return t;
}
void rbFree(RNode *t) {
  if (t == NULL) return;
  rbFree(t->l);
  rbFree(t->r);
  free(t);
}
Complexity: O(log n)

