C · red-black trees · transformation · L3
Concept: A rotation must hand the old root's color to the new root and color the old root red
Misconception: A rotation only moves pointers; colors stay where they are.
Explanation: In a left-leaning red-black tree a rotation turns a right-leaning red link into a left-leaning one. The node that moves up takes the color of the node it replaces, so the color of the subtree's top link is unchanged, and the node that moves down becomes red. Not copying the color changes the black count above the subtree.
Incorrect:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
RNode *rotateLeftBad(RNode *h) {
  RNode *x = h->r;
  h->r = x->l;
  x->l = h;
  h->red = 1;
  return x;
}
Correct:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
RNode *rbNew(int key) {
  RNode *n = malloc(sizeof *n);
  if (n == NULL) return NULL;
  n->key = key;
  n->red = 1;
  n->l = n->r = NULL;
  return n;
}
RNode *rotateLeft(RNode *h) {
  RNode *x = h->r;
  h->r = x->l;
  x->l = h;
  x->red = h->red;
  h->red = 1;
  return x;
}
RNode *rotateRight(RNode *h) {
  RNode *x = h->l;
  h->l = x->r;
  x->r = h;
  x->red = h->red;
  h->red = 1;
  return x;
}
void flipColors(RNode *h) {
  h->red = !h->red;
  h->l->red = !h->l->red;
  h->r->red = !h->r->red;
}
Complexity: O(1)

