C · segment trees · access · L3
Concept: A range query returns the identity for a disjoint node, the stored value for a covered node, and recurses otherwise
Misconception: A range query can return a leaf value as soon as it reaches a leaf.
Explanation: Each node covers [lo, hi]. If it is disjoint from the query, it contributes nothing (0 for sums). If it is fully inside the query, its stored value is used. Otherwise both children are visited. Returning at a leaf without the disjoint test adds elements outside the range. At most about four nodes per level are visited, so a query is O(log n).
Incorrect:
static long long qrecBad(const long long *t, size_t node, size_t lo, size_t hi,
                         size_t l, size_t r) {
  if (l <= lo && hi <= r) return t[node];
  if (lo == hi) return t[node];
  size_t mid = lo + (hi - lo) / 2;
  return qrecBad(t, 2 * node + 1, lo, mid, l, r) +
         qrecBad(t, 2 * node + 2, mid + 1, hi, l, r);
}
long long segQueryBad(const long long *t, size_t n, size_t l, size_t r) {
  return qrecBad(t, 0, 0, n - 1, l, r);
}
Correct:
static long long qrec(const long long *t, size_t node, size_t lo, size_t hi,
                      size_t l, size_t r) {
  if (r < lo || hi < l) return 0;
  if (l <= lo && hi <= r) return t[node];
  size_t mid = lo + (hi - lo) / 2;
  return qrec(t, 2 * node + 1, lo, mid, l, r) +
         qrec(t, 2 * node + 2, mid + 1, hi, l, r);
}
long long segQuery(const SegTree *s, size_t l, size_t r) {
  if (s->n == 0 || l > r || r >= s->n) return 0;
  return qrec(s->t, 0, 0, s->n - 1, l, r);
}
Complexity: O(log n)

