C · tries (prefix trees) · creation · L1
Concept: Map a letter to a child slot with c - 'a'; using the character code directly indexes far past the 26 children
Misconception: The character itself can index the child array.
Explanation: Each trie node has one child pointer per letter. The index of a lowercase letter is c - 'a' (0 to 25); the character code of 'c' is 99, which is outside an array of 26. Validate the word first, create missing children with calloc so every link starts NULL, and mark the last node as the end of a word.
Incorrect (undefined behaviour reported by the sanitizer: out of bounds):
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
void trieInsertBad(TrieNode *root, const char *w) {
  TrieNode *t = root;
  for (; *w != '\0'; w++) {
    if (t->next[(int)*w] == NULL) t->next[(int)*w] = trieNew();
    t = t->next[(int)*w];
  }
  t->end = 1;
}
Correct:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
int trieInsert(TrieNode *root, const char *w) {
  for (const char *p = w; *p != '\0'; p++)
    if (*p < 'a' || *p > 'z') return 0;
  TrieNode *t = root;
  for (; *w != '\0'; w++) {
    int i = *w - 'a';
    if (t->next[i] == NULL) {
      t->next[i] = trieNew();
      if (t->next[i] == NULL) return 0;
    }
    t = t->next[i];
  }
  t->end = 1;
  return 1;
}
void trieFree(TrieNode *t) {
  if (t == NULL) return;
  for (int i = 0; i < 26; i++) trieFree(t->next[i]);
  free(t);
}
Complexity: O(len)

