C · tries (prefix trees) · patterns · L2
Concept: Count the words under a prefix by counting end flags in its subtree, not the nodes
Misconception: The number of nodes below a prefix is the number of matching words.
Explanation: Nodes are shared between words, and a long word contributes a node for every letter, so node counts say nothing about word counts. Descend to the prefix node, then sum the end flags of the whole subtree. This is the core of autocomplete: O(len + size of the subtree).
Incorrect:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
const TrieNode *trieFind(const TrieNode *root, const char *p) {
  const TrieNode *t = root;
  for (; *p != '\0'; p++) {
    if (*p < 'a' || *p > 'z') return NULL;
    t = t->next[*p - 'a'];
    if (t == NULL) return NULL;
  }
  return t;
}
size_t trieCountNodes(const TrieNode *n) {
  if (n == NULL) return 0;
  size_t c = 0;
  for (int i = 0; i < 26; i++)
    if (n->next[i] != NULL) c += 1 + trieCountNodes(n->next[i]);
  return c;
}
size_t trieCountPrefixBad(const TrieNode *root, const char *p) {
  return trieCountNodes(trieFind(root, p));
}
Correct:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
const TrieNode *trieFind(const TrieNode *root, const char *p) {
  const TrieNode *t = root;
  for (; *p != '\0'; p++) {
    if (*p < 'a' || *p > 'z') return NULL;
    t = t->next[*p - 'a'];
    if (t == NULL) return NULL;
  }
  return t;
}
size_t trieCountWords(const TrieNode *n) {
  if (n == NULL) return 0;
  size_t c = n->end ? 1 : 0;
  for (int i = 0; i < 26; i++) c += trieCountWords(n->next[i]);
  return c;
}
size_t trieCountPrefix(const TrieNode *root, const char *p) {
  return trieCountWords(trieFind(root, p));
}
Complexity: O(len + subtree)

