C · tries (prefix trees) · access · L1
Concept: A word is stored only if the node you reach is marked as an end; reaching a node only proves a prefix
Misconception: If the path for a string exists, the string is in the trie.
Explanation: Walking the letters of "ca" in a trie holding "cart" succeeds, but "ca" was never inserted. The end flag distinguishes a stored word from a mere prefix. Prefix queries ignore the flag. Both operations cost O(length of the query), independent of how many words are stored.
Incorrect:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
const TrieNode *trieFind(const TrieNode *root, const char *p) {
  const TrieNode *t = root;
  for (; *p != '\0'; p++) {
    if (*p < 'a' || *p > 'z') return NULL;
    t = t->next[*p - 'a'];
    if (t == NULL) return NULL;
  }
  return t;
}
int trieContainsBad(const TrieNode *root, const char *w) { return trieFind(root, w) != NULL; }
Correct:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
const TrieNode *trieFind(const TrieNode *root, const char *p) {
  const TrieNode *t = root;
  for (; *p != '\0'; p++) {
    if (*p < 'a' || *p > 'z') return NULL;
    t = t->next[*p - 'a'];
    if (t == NULL) return NULL;
  }
  return t;
}
int trieContains(const TrieNode *root, const char *w) {
  const TrieNode *n = trieFind(root, w);
  return n != NULL && n->end;
}
int trieStartsWith(const TrieNode *root, const char *p) { return trieFind(root, p) != NULL; }
Complexity: O(len)

