Context: platform: STM32_HAL
Embedded C · STM32_HAL · serial framing · iteration · Intermediate
Concept: Decode COBS by copying each block and restoring the zero between blocks only
Misconception: Every block in a COBS stream is followed by a zero byte.
Explanation: Each block starts with a count c: copy the next c - 1 bytes, then restore a zero unless the block was a full 0xFF block or it is the last block. Adding a zero after the last block yields an extra trailing byte that was never in the original data.
Incorrect:
size_t cobsDecBad(const uint8_t *in, size_t n, uint8_t *out) {
  size_t oi = 0, i = 0;
  while (i < n) {
    uint8_t code = in[i++];
    for (uint8_t k = 1; k < code && i < n; k++) out[oi++] = in[i++];
    if (code != 0xFF) out[oi++] = 0;
  }
  return oi;
}
Correct:
size_t cobsDecode(const uint8_t *in, size_t n, uint8_t *out) {
  size_t oi = 0, i = 0;
  while (i < n) {
    uint8_t code = in[i++];
    for (uint8_t k = 1; k < code && i < n; k++) out[oi++] = in[i++];
    if (code != 0xFF && i < n) out[oi++] = 0;
  }
  return oi;
}
Complexity: O(n)

