Context: platform: STM32_HAL
Embedded C · STM32_HAL · serial framing · iteration · Intermediate
Concept: Decode SLIP one byte at a time with an escape flag
Misconception: The decoder can treat every byte after 0xDB as data.
Explanation: A byte-at-a-time decoder keeps a flag that says the previous byte was ESC. After ESC, 0xDC means 0xC0 and 0xDD means 0xDB. END with at least one data byte ends a packet; an empty packet (two END bytes in a row) is ignored. Treating the byte after ESC as itself turns 0xDB 0xDC into two data bytes.
Incorrect:
typedef struct { uint8_t buf[32]; size_t n; int esc; } SlipRx;
int slipRxBad(SlipRx *r, uint8_t c) {
  if (c == 0xC0) { int done = r->n > 0; return done; }
  if (r->n < sizeof r->buf) r->buf[r->n++] = c;
  return 0;
}
Correct:
typedef struct { uint8_t buf[32]; size_t n; int esc; } SlipRx;
int slipRx(SlipRx *r, uint8_t c) {
  if (c == 0xC0) { r->esc = 0; return r->n > 0; }
  if (c == 0xDB && !r->esc) { r->esc = 1; return 0; }
  if (r->esc) { c = (c == 0xDC) ? 0xC0 : (c == 0xDD) ? 0xDB : c; r->esc = 0; }
  if (r->n < sizeof r->buf) r->buf[r->n++] = c;
  return 0;
}
Complexity: O(1)

