Context: platform: STM32_HAL
Embedded C · STM32_HAL · packet parsing · iteration · Intermediate
Concept: Parse the frame AA, length, payload, checksum one byte at a time with a state machine and a length limit
Misconception: The length byte from the wire can be trusted to fit the buffer.
Explanation: A byte-at-a-time parser keeps its position in a state variable: wait for the sync byte 0xAA, read the length, read that many payload bytes while summing them, then compare the next byte with the sum. The length comes from an untrusted source, so reject zero and anything above the buffer size before storing a byte; without that check a corrupt length writes past the end of the buffer. After the checksum byte the parser always goes back to the sync state.
Incorrect (undefined behaviour reported by the sanitizer: stack-buffer-overflow):
#define PMAX 16
typedef enum { P_SYNC, P_LEN, P_DATA, P_SUM } PState;
typedef struct { PState st; uint8_t len, idx, sum; uint8_t buf[PMAX]; } Parser;
int pktFeedBad(Parser *p, uint8_t b) {
  switch (p->st) {
  case P_SYNC: if (b == 0xAA) p->st = P_LEN; break;
  case P_LEN: p->len = b; p->idx = 0; p->sum = b; p->st = P_DATA; break;
  case P_DATA:
    p->buf[p->idx++] = b; p->sum = (uint8_t)(p->sum + b);
    if (p->idx == p->len) p->st = P_SUM;
    break;
  case P_SUM: p->st = P_SYNC; return b == p->sum;
  }
  return 0;
}
Correct:
#define PMAX 16
typedef enum { P_SYNC, P_LEN, P_DATA, P_SUM } PState;
typedef struct { PState st; uint8_t len, idx, sum; uint8_t buf[PMAX]; } Parser;
int pktFeed(Parser *p, uint8_t b) {
  switch (p->st) {
  case P_SYNC: if (b == 0xAA) p->st = P_LEN; break;
  case P_LEN:
    if (b == 0 || b > PMAX) { p->st = P_SYNC; break; }
    p->len = b; p->idx = 0; p->sum = b; p->st = P_DATA;
    break;
  case P_DATA:
    p->buf[p->idx++] = b; p->sum = (uint8_t)(p->sum + b);
    if (p->idx == p->len) p->st = P_SUM;
    break;
  case P_SUM: p->st = P_SYNC; return b == p->sum;
  }
  return 0;
}
Complexity: O(1)

