Context: platform: STM32_HAL
Embedded C · STM32_HAL · packet parsing · creation · Intermediate
Concept: Hand bytes from an interrupt to the parser through a single-producer single-consumer ring buffer
Misconception: A ring buffer is full when head equals tail.
Explanation: The interrupt writes at head and the main loop reads at tail. If both positions can be equal when the buffer is empty and when it is full, the two cases are indistinguishable. Give up one slot: the buffer is empty when head == tail and full when advancing head would reach tail. With a power-of-two size the wrap is a mask. Only the interrupt changes head and only the main loop changes tail, so no lock is needed for one producer and one consumer on a single core.
Incorrect:
#define RB 8
typedef struct { volatile uint8_t head, tail; uint8_t d[RB]; } Ring;
int rbPushBad(Ring *r, uint8_t b) {
  r->d[r->head] = b; r->head = (uint8_t)((r->head + 1) & (RB - 1));
  return 1;
}
Correct:
#define RB 8
typedef struct { volatile uint8_t head, tail; uint8_t d[RB]; } Ring;
int rbPush(Ring *r, uint8_t b) {
  uint8_t next = (uint8_t)((r->head + 1) & (RB - 1));
  if (next == r->tail) return 0;
  r->d[r->head] = b; r->head = next;
  return 1;
}
int rbPop(Ring *r, uint8_t *b) {
  if (r->head == r->tail) return 0;
  *b = r->d[r->tail]; r->tail = (uint8_t)((r->tail + 1) & (RB - 1));
  return 1;
}
Complexity: O(1)

