Context: platform: STM32_HAL
Embedded C · STM32_HAL · static allocation · patterns · Intermediate
Concept: Free resources on every exit path of a function by jumping to one cleanup label
Misconception: A function that allocates a buffer is finished when it returns an error code.
Explanation: Each early return that follows an allocation must release it, or the memory leaks a little on every failure. A single cleanup label at the end of the function, reached with goto on every error, keeps the release in one place. Counting live allocations in a debug build shows a leak as a number that does not return to zero.
Incorrect:
static int live;
static void *lastp;
void *xalloc(size_t n) { live++; lastp = malloc(n); return lastp; }
void xfree(void *p) { if (p) { live--; free(p); } }
int parseBad(int fail) {
  uint8_t *b = xalloc(16);
  if (!b) return -1;
  if (fail) return -2;
  xfree(b);
  return 0;
}
Correct:
static int live;
static void *lastp;
void *xalloc(size_t n) { live++; lastp = malloc(n); return lastp; }
void xfree(void *p) { if (p) { live--; free(p); } }
int parseOk(int fail) {
  int rc = 0;
  uint8_t *b = xalloc(16);
  if (!b) return -1;
  if (fail) { rc = -2; goto done; }
done:
  xfree(b);
  return rc;
}
Complexity: O(1)

