Context: platform: STM32_HAL
Embedded C · STM32_HAL · static allocation · creation · Intermediate
Concept: Build a fixed-size block pool with a free list so allocation never fragments
Misconception: Freeing a block twice is harmless.
Explanation: A pool hands out equal-sized blocks from a static array. A free list threaded through the free blocks makes allocation and release constant-time and free of fragmentation. Releasing a block that is already free would put it on the list twice and then give the same block to two owners, so the release function should reject a block that is not in use. Keep one flag per block, or search the list, and return an error on a double free.
Incorrect:
#define NB 4
typedef struct { uint8_t used[NB]; uint32_t blk[NB][4]; } Pool;
void *poolAllocBad(Pool *p) {
  for (int i = 0; i < NB; i++) if (!p->used[i]) { p->used[i] = 1; return p->blk[i]; }
  return NULL;
}
void poolFreeBad(Pool *p, void *b) {
  int i = (int)((uint32_t (*)[4])b - p->blk);
  p->used[i] = 0;
}
Correct:
#define NB 4
typedef struct { uint8_t used[NB]; uint32_t blk[NB][4]; } Pool;
void *poolAlloc(Pool *p) {
  for (int i = 0; i < NB; i++) if (!p->used[i]) { p->used[i] = 1; return p->blk[i]; }
  return NULL;
}
int poolFree(Pool *p, void *b) {
  if ((uint32_t (*)[4])b < p->blk || (uint32_t (*)[4])b >= p->blk + NB) return -1;
  int i = (int)((uint32_t (*)[4])b - p->blk);
