    for t in tasks:
        if t["due"] <= now:
            return t["name"]
Correct:
def pick(tasks, now):
    ready = [t for t in tasks if t["due"] <= now]
    if not ready:
        return None
    return min(ready, key=lambda t: t["due"])["name"]
Complexity: O(n)

