  m[v].count { |w| w != 0 }
end
Correct:
class MatrixGraph
  def out_degree(v)
    @matrix[v].count { |w| w != 0 }
  end
  def in_degree(v)
    @matrix.count { |row| row[v] != 0 }
  end
end
Complexity: O(V)

