    @size += 1
    true
  end
  def pop_front
    return nil if empty?
    v = @buf[@head]
    @buf[@head] = nil
    @head = (@head + 1) % @buf.size
    @size -= 1
    v
  end
  def pop_back
    return nil if empty?
    i = (@head + @size - 1) % @buf.size
    v = @buf[i]
    @buf[i] = nil
    @size -= 1
    v
  end
  def front
    empty? ? nil : @buf[@head]
  end
  def back
    empty? ? nil : @buf[(@head + @size - 1) % @buf.size]
  end
  def each
    return to_enum(:each) unless block_given?
    @size.times { |i| yield @buf[(@head + i) % @buf.size] }
  end
end

