TypeScript · binarytree · ordering · L2
Concept: An iterative preorder pushes the right child first so the left child pops first
Misconception: Push left then right to visit left first.
Explanation: A stack pops the last item pushed. To visit left before right, push right first. Pushing left first visits the right subtree first, which produces a mirrored preorder. The same reasoning applies to every stack based depth first search.
Incorrect:
function preorderBad<T>(root: TreeNode<T> | null): T[] {
  const out: T[] = [];
  const stack: Array<TreeNode<T>> = root ? [root] : [];
  while (stack.length > 0) {
    const n = stack.pop() as TreeNode<T>;
    out.push(n.val);
    if (n.left) stack.push(n.left);
    if (n.right) stack.push(n.right);
  }
  return out;
}
Correct:
function preorder<T>(root: TreeNode<T> | null): T[] {
  const out: T[] = [];
  const stack: Array<TreeNode<T>> = root ? [root] : [];
  while (stack.length > 0) {
    const n = stack.pop() as TreeNode<T>;
    out.push(n.val);
    if (n.right) stack.push(n.right);
    if (n.left) stack.push(n.left);
  }
  return out;
}
Complexity: O(n)

