document:
TypeScript · bst · insertion-and-deletion · L1
Concept: A recursive insert must assign the returned subtree back to the child link
Misconception: Recursing into n.left is enough; the callee attaches the new node.
Explanation: When the child is null, the recursive call creates a node and returns it, but it cannot change the parent link by itself. The caller must write the result back with n.left = insert(n.left, ...). Ignoring the return value drops every key that would become a new leaf.
Incorrect:
function insertBad<K>(n: BNode<K> | null, key: K, cmp: Cmp<K>): BNode<K> {
  if (n === null) return new BNode(key);
  if (cmp(key, n.key) < 0) insertBad(n.left, key, cmp);
  else insertBad(n.right, key, cmp);
  return n;
}
Correct:
type Cmp<K> = (a: K, b: K) => number;
const numCmp: Cmp<number> = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
class BNode<K> {
  constructor(
    public key: K,
    public left: BNode<K> | null = null,
    public right: BNode<K> | null = null,
  ) {}
}
function insert<K>(n: BNode<K> | null, key: K, cmp: Cmp<K>): BNode<K> {
  if (n === null) return new BNode(key);
  const c = cmp(key, n.key);
  if (c < 0) n.left = insert(n.left, key, cmp);
  else if (c > 0) n.right = insert(n.right, key, cmp);
  return n;
}
function inorder<K>(n: BNode<K> | null): K[] {
  return n === null ? [] : [...inorder(n.left), n.key, ...inorder(n.right)];
}
Complexity: O(h)

