TypeScript · btree · testing · L3
Concept: A B-tree checker verifies key counts, order and equal leaf depth, not only sortedness
Misconception: If the keys of every node are sorted, the tree is a valid B-tree.
Explanation: A B-tree also needs every non-root node to hold between t-1 and 2t-1 keys, every internal node to have one more child than keys, and all leaves to be at the same depth. Return the leaf depth from each subtree or -1 when any rule fails.
Incorrect:
function sortedOnlyBad(x: BNode): boolean {
  for (let i = 1; i < x.keys.length; i++) {
    if ((x.keys[i - 1] as number) >= (x.keys[i] as number)) return false;
  }
  return x.children.every(sortedOnlyBad);
}
Correct:
function checkB(x: BNode, t: number, isRoot = true): number {
  const n = x.keys.length;
  if (n > 2 * t - 1 || (!isRoot && n < t - 1)) return -1;
  for (let i = 1; i < n; i++) {
    if ((x.keys[i - 1] as number) >= (x.keys[i] as number)) return -1;
  }
  if (x.leaf) return 0;
  if (x.children.length !== n + 1) return -1;
  let depth = -2;
  for (const c of x.children) {
    const d = checkB(c, t, false);
    if (d < 0) return -1;
    if (depth === -2) depth = d;
    else if (d !== depth) return -1;
  }
  return depth + 1;
}
Complexity: O(n)

