TypeScript · btree · iteration · L3
Concept: A range scan visits the child before the first key above the upper bound before it stops
Misconception: Stop as soon as a key is above the upper bound.
Explanation: The child to the left of a key holds values smaller than that key, and some of them can still be inside the range. Visit that child first, then stop at the key. Child subtrees whose keys are all below the lower bound are skipped without a visit.
Incorrect:
function rangeBad(x: BNode, lo: number, hi: number, out: number[] = []): number[] {
  for (let i = 0; i < x.keys.length; i++) {
    const k = x.keys[i] as number;
    if (k < lo) continue;
    if (k > hi) return out;
    if (!x.leaf) rangeBad(x.children[i] as BNode, lo, hi, out);
    out.push(k);
  }
  if (!x.leaf) rangeBad(x.children[x.keys.length] as BNode, lo, hi, out);
  return out;
}
Correct:
function range(x: BNode, lo: number, hi: number, out: number[] = []): number[] {
  for (let i = 0; i < x.keys.length; i++) {
    const k = x.keys[i] as number;
    if (k < lo) continue;
    if (!x.leaf) range(x.children[i] as BNode, lo, hi, out);
    if (k > hi) return out;
    out.push(k);
  }
  if (!x.leaf) range(x.children[x.keys.length] as BNode, lo, hi, out);
  return out;
}
Complexity: O(log n + m)

