document:
TypeScript · btree · insertion-and-deletion · L2
Concept: A split moves the median up and removes it from the child so it appears once
Misconception: Copy the median key into the parent and keep the child as is.
Explanation: The median becomes the separator in the parent, so it must leave the child. Copying it and keeping a copy in the left half stores the key twice and breaks the sorted order. Give the upper keys (and upper children) to a new right sibling, truncate the child to t-1 keys, and insert the median and the sibling in the parent.
Incorrect:
function splitChildBad(p: BNode, i: number, t: number): void {
  const y = p.children[i] as BNode;
  const z = new BNode(y.leaf);
  z.keys = y.keys.splice(t);
  if (!y.leaf) z.children = y.children.splice(t);
  p.keys.splice(i, 0, y.keys[t - 1] as number);
  p.children.splice(i + 1, 0, z);
}
Correct:
function splitChild(p: BNode, i: number, t: number): void {
  const y = p.children[i] as BNode;
  const z = new BNode(y.leaf);
  const median = y.keys[t - 1] as number;
  z.keys = y.keys.splice(t);
  y.keys.length = t - 1;
  if (!y.leaf) z.children = y.children.splice(t);
  p.keys.splice(i, 0, median);
  p.children.splice(i + 1, 0, z);
}
Complexity: O(t)

