TypeScript · directedgraph · patterns · L3
Concept: Cycle detection needs three states; a seen flag reports a cycle for any node reached twice
Misconception: If DFS reaches a visited node again, there is a cycle.
Explanation: In a DAG a node can be reached by two different paths (a diamond) without any cycle. A cycle exists only when DFS reaches a node that is still on the current recursion stack. Use three states: unvisited, on the stack, and finished.
Incorrect:
function hasCycleBad(g: DiGraph): boolean {
  const seen = new Array<boolean>(g.n).fill(false);
  const visit = (u: number): boolean => {
    seen[u] = true;
    for (const v of g.adj[u] as number[]) {
      if (seen[v] || visit(v)) return true;
    }
    return false;
  };
  for (let u = 0; u < g.n; u++) if (!seen[u] && visit(u)) return true;
  return false;
}
Correct:
function hasCycle(g: DiGraph): boolean {
  const state = new Array<number>(g.n).fill(0);
  const visit = (u: number): boolean => {
    state[u] = 1;
    for (const v of g.adj[u] as number[]) {
      if (state[v] === 1) return true;
      if (state[v] === 0 && visit(v)) return true;
    }
    state[u] = 2;
    return false;
  };
  for (let u = 0; u < g.n; u++) if (state[u] === 0 && visit(u)) return true;
  return false;
}
Complexity: O(V + E)

