TypeScript · disjointset · complexity · L3
Concept: Union by size attaches the smaller tree under the larger, keeping trees shallow
Misconception: Always attaching the first root under the second gives balanced trees.
Explanation: If every union attaches the first root under the second, a sequence of unions can build one long chain of depth n. Attaching the smaller tree under the larger one limits the height to log n. Track sizes at the roots and update the larger root after merging.
Incorrect:
function unionNaive(parent: number[], a: number, b: number): void {
  parent[findCompress(parent, a)] = findCompress(parent, b);
}
Correct:
class UnionFind {
  parent: number[];
  size: number[];
  count: number;
  constructor(n: number) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.size = Array.from({ length: n }, () => 1);
    this.count = n;
  }
  find(x: number): number {
    let root = x;
    while (this.parent[root] !== root) root = this.parent[root] as number;
    while (this.parent[x] !== root) {
      const next = this.parent[x] as number;
      this.parent[x] = root;
      x = next;
    }
    return root;
  }
  union(a: number, b: number): boolean {
    let ra = this.find(a);
    let rb = this.find(b);
    if (ra === rb) return false;
    if ((this.size[ra] as number) < (this.size[rb] as number)) [ra, rb] = [rb, ra];
    this.parent[rb] = ra;
    this.size[ra] = (this.size[ra] as number) + (this.size[rb] as number);
    this.count--;
    return true;
  }
  connected(a: number, b: number): boolean { return this.find(a) === this.find(b); }
}
Complexity: O(alpha(n))

