TypeScript · heap · insertion-and-deletion · L2
Concept: Sift-down swaps with the smaller child; always taking the left child breaks the heap
Misconception: After moving the last element to the root, swap it with the left child until it is smaller.
Explanation: The root must end up smaller than both children, so it should swap with the smaller one. Taking the left child unconditionally can put a larger value above a smaller sibling. Compare both children, pick the smaller (for a min-heap), and stop when neither is smaller than the node.
Incorrect:
function siftDownLeft(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    if (l >= n || (a[l] as number) >= (a[i] as number)) return;
    [a[i], a[l]] = [a[l] as number, a[i] as number];
    i = l;
  }
}
Correct:
function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
Complexity: O(log n)

