TypeScript · heap · ordering · L3
Concept: Heap sort builds a max-heap and moves the maximum to the end; a min-heap yields descending order
Misconception: Using a min-heap and swapping the root to the end sorts ascending.
Explanation: Each extraction moves the root to the end of the array. If the root is the smallest value the array ends up in descending order. Heap sort in place needs a max-heap: build it, then repeatedly swap the root with the last unsorted slot and sift down over the shrunken range. It runs in O(n log n) with O(1) extra space.
Incorrect:
function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
function heapSortBad(a: number[]): number[] {
  for (let i = (a.length >> 1) - 1; i >= 0; i--) siftDown(a, i, a.length);
  for (let end = a.length - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end] as number, a[0] as number];
    siftDown(a, 0, end);
  }
  return a;
}
Correct:
function siftDownMax(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) > (a[m] as number)) m = l;
    if (r < n && (a[r] as number) > (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
function heapSort(a: number[]): number[] {
  for (let i = (a.length >> 1) - 1; i >= 0; i--) siftDownMax(a, i, a.length);
  for (let end = a.length - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end] as number, a[0] as number];
    siftDownMax(a, 0, end);
  }
  return a;
}
Complexity: O(n log n)

