TypeScript · linkedlist · patterns · L3
Concept: Merging two sorted lists needs a dummy head and must attach the remaining nodes at the end
Misconception: The merge loop is finished when one list runs out.
Explanation: When one list is exhausted, the other still holds its largest values. Forgetting to attach the remainder truncates the result. Use a dummy head to avoid special-casing the first node and finish with tail.next = a ?? b.
Incorrect:
type ListNode<T> = { value: T; next: ListNode<T> | null };
type NumList = ListNode<number> | null;
function mergeBad(a: NumList, b: NumList): NumList {
  const dummy: ListNode<number> = { value: 0, next: null };
  let tail = dummy;
  while (a && b) {
    if (a.value <= b.value) { tail.next = a; a = a.next; } else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  return dummy.next;
}
Correct:
type ListNode<T> = { value: T; next: ListNode<T> | null };
type NumList = ListNode<number> | null;
function merge(a: NumList, b: NumList): NumList {
  const dummy: ListNode<number> = { value: 0, next: null };
