TypeScript · linkedlist · insertion-and-deletion · L2
Concept: Delete with a dummy head: it handles removing the first node and does not skip the node after a deletion
Misconception: Looking one node ahead (cur.next) is enough to delete any value.
Explanation: Looking ahead from the head never examines the head itself, so a matching first node stays. Advancing cur after a deletion also skips the next node, so consecutive matches survive. A dummy node before the head removes the special case, and cur advances only when nothing was deleted.
Incorrect:
type ListNode<T> = { value: T; next: ListNode<T> | null };
function removeBad<T>(head: ListNode<T> | null, v: T): ListNode<T> | null {
  let cur = head;
  while (cur?.next) {
    if (cur.next.value === v) cur.next = cur.next.next;
    cur = cur.next;
  }
  return head;
}
Correct:
type ListNode<T> = { value: T; next: ListNode<T> | null };
function remove<T>(head: ListNode<T> | null, v: T): ListNode<T> | null {
  const dummy: ListNode<T> = { value: v, next: head };
  let cur = dummy;
  while (cur.next) {
    if (cur.next.value === v) cur.next = cur.next.next;
    else cur = cur.next;
  }
  return dummy.next;
}
Complexity: O(n)

