document:
TypeScript · priorityqueue · ordering · L2
Concept: A heap is not stable; break ties with an insertion counter to keep first-in order
Misconception: Equal-priority items come out in the order they were pushed.
Explanation: A binary heap makes no promise about equal keys: sift operations reorder them. For tasks of the same priority add a sequence number and compare by priority first and sequence second. That gives FIFO among equals.
Incorrect:
type Task = { p: number; id: number };
function drainBad(ids: number[]): number[] {
  const q = new PriorityQueue<Task>((a, b) => a.p - b.p);
  for (const id of ids) q.push({ p: 1, id });
  const out: number[] = [];
  for (let t = q.pop(); t; t = q.pop()) out.push(t.id);
  return out;
}
Correct:
type Task = { p: number; id: number };
function drain(ids: number[]): number[] {
  let seq = 0;
  const q = new PriorityQueue<Task & { seq: number }>((a, b) => a.p - b.p || a.seq - b.seq);
  for (const id of ids) q.push({ p: 1, id, seq: seq++ });
  const out: number[] = [];
  for (let t = q.pop(); t; t = q.pop()) out.push(t.id);
  return out;
}
Complexity: O(n log n)

