TypeScript · queue · patterns · L3
Concept: Level-order traversal needs the queue size at the start of each level
Misconception: Processing nodes until the queue is empty gives the nodes level by level.
Explanation: The loop visits nodes in level order, but without a boundary every value lands in one flat list. Capture const n = queue.length at the start of each level and process exactly n nodes, collecting them in a per-level array.
Incorrect:
type TNode = { val: number; left: TNode | null; right: TNode | null };
function levelsBad(root: TNode | null): number[][] {
  const out: number[][] = [];
  const q: TNode[] = root ? [root] : [];
  while (q.length) {
    const n = q.shift() as TNode;
    out.push([n.val]);
    if (n.left) q.push(n.left);
    if (n.right) q.push(n.right);
  }
  return out;
}
Correct:
type TNode = { val: number; left: TNode | null; right: TNode | null };
function levels(root: TNode | null): number[][] {
  const out: number[][] = [];
  const q: TNode[] = root ? [root] : [];
  while (q.length) {
    const row: number[] = [];
    for (let n = q.length; n > 0; n--) {
      const node = q.shift() as TNode;
      row.push(node.val);
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    out.push(row);
  }
  return out;
}
Complexity: O(n)

