TypeScript · redblacktree · mutation · L2
Concept: A rotation hands the old root colour to the new root and colours the demoted node red
Misconception: A rotation only rearranges the links.
Explanation: The subtree keeps the same colour at its top after a rotation, or black heights above it change. The new root takes the colour of the old root, and the demoted old root becomes red. Rotating links without copying the colour can leave a red root of the subtree under a red parent.
Incorrect:
function rotateLeftBad<K>(h: RbNode<K>): RbNode<K> {
  const x = h.right as RbNode<K>;
  h.right = x.left;
  x.left = h;
  h.color = RED;
  return x;
}
Correct:
const RED = true;
const BLACK = false;
class RbNode<K> {
  constructor(
    public key: K,
    public color: boolean = RED,
    public left: RbNode<K> | null = null,
    public right: RbNode<K> | null = null,
  ) {}
}
function isRed<K>(n: RbNode<K> | null): boolean {
  return n !== null && n.color === RED;
}
function rotateLeft<K>(h: RbNode<K>): RbNode<K> {
  const x = h.right as RbNode<K>;
  h.right = x.left;
  x.left = h;
  x.color = h.color;
  h.color = RED;
  return x;
}
function rotateRight<K>(h: RbNode<K>): RbNode<K> {
  const x = h.left as RbNode<K>;
  h.left = x.right;
  x.right = h;
  x.color = h.color;
  h.color = RED;
  return x;
}
Complexity: O(1)

