TypeScript · segmenttree · creation · L2
Concept: Build combines both children into every internal node, not just one
Misconception: An internal node can copy the value of its left child.
Explanation: Each internal node stores the combined value of its range, which is the left child plus the right child for a sum. Copying only one child makes every internal node ignore half of its range, so queries answered from internal nodes are wrong.
Incorrect:
function buildBad(a: number[], tree: number[], node: number, l: number, r: number): void {
  if (l === r) { tree[node] = a[l] as number; return; }
  const mid = (l + r) >> 1;
  buildBad(a, tree, 2 * node, l, mid);
  buildBad(a, tree, 2 * node + 1, mid + 1, r);
  tree[node] = tree[2 * node] as number;
}
Correct:
class SegTree {
  n: number;
  tree: number[];
  constructor(a: number[]) {
    this.n = a.length;
    this.tree = new Array<number>(4 * Math.max(1, this.n)).fill(0);
    if (this.n > 0) this.build(a, 1, 0, this.n - 1);
  }
  build(a: number[], node: number, l: number, r: number): void {
    if (l === r) {
      this.tree[node] = a[l] as number;
      return;
    }
    const mid = (l + r) >> 1;
    this.build(a, 2 * node, l, mid);
    this.build(a, 2 * node + 1, mid + 1, r);
    this.tree[node] = (this.tree[2 * node] as number) + (this.tree[2 * node + 1] as number);
  }
}
Complexity: O(n)

