document:
TypeScript · segmenttree · access · L2
Concept: A range query returns a whole node only when its range is inside the query, and zero when it is outside
Misconception: Return the node value whenever its range overlaps the query.
Explanation: A node can be used as is only when its range lies completely inside the query range. When it partly overlaps, the query must descend into both children. Returning the node on any overlap includes elements outside the query. Ranges fully outside contribute the identity, which is 0 for a sum.
Incorrect:
function queryBad(
  t: SegTree, ql: number, qr: number, node = 1, l = 0, r = t.n - 1,
): number {
  if (qr < l || r < ql) return 0;
  return t.tree[node] as number;
}
Correct:
function sumRange(
  t: SegTree, ql: number, qr: number, node = 1, l = 0, r = t.n - 1,
): number {
  if (qr < l || r < ql) return 0;
  if (ql <= l && r <= qr) return t.tree[node] as number;
  const mid = (l + r) >> 1;
  const left = sumRange(t, ql, qr, 2 * node, l, mid);
  return left + sumRange(t, ql, qr, 2 * node + 1, mid + 1, r);
}
Complexity: O(log n)

