document:
TypeScript · undirectedgraph · patterns · L3
Concept: Bipartite checks must start a colouring from every uncoloured vertex
Misconception: Colour the graph from vertex 0 and check for conflicts.
Explanation: A graph with several components is bipartite only if each component is. A search from vertex 0 colours only the first component, so an odd cycle in another one goes unnoticed. Loop over all vertices and start a new colouring for each one that is still uncoloured.
Incorrect:
function isBipartiteBad(g: UGraph): boolean {
  const color = new Array<number>(g.n).fill(-1);
  color[0] = 0;
  const queue = [0];
  for (let i = 0; i < queue.length; i++) {
    const u = queue[i] as number;
    for (const v of g.adj[u] as Set<number>) {
      if (color[v] === -1) { color[v] = 1 - (color[u] as number); queue.push(v); }
      else if (color[v] === color[u]) return false;
    }
  }
  return true;
}
Correct:
function isBipartite(g: UGraph): boolean {
  const color = new Array<number>(g.n).fill(-1);
  for (let s = 0; s < g.n; s++) {
    if (color[s] !== -1) continue;
    color[s] = 0;
    const queue = [s];
    for (let i = 0; i < queue.length; i++) {
      const u = queue[i] as number;
      for (const v of g.adj[u] as Set<number>) {
        if (color[v] === -1) { color[v] = 1 - (color[u] as number); queue.push(v); }
        else if (color[v] === color[u]) return false;
      }
    }
  }
  return true;
}
Complexity: O(V + E)

