TypeScript · undirectedgraph · patterns · L2
Concept: A path rebuilt from parent links runs target to source and must be reversed
Misconception: Following parent links from the target gives the path in order.
Explanation: Parent pointers lead from the target back to the source, so walking them produces the path backwards. Reverse the list before returning it. Return an empty list when the target was never reached.
Incorrect:
function pathBad(g: UGraph, s: number, t: number): number[] {
  const prev = new Array<number>(g.n).fill(-2);
  prev[s] = -1;
  const queue = [s];
  for (let i = 0; i < queue.length; i++) {
    for (const v of g.adj[queue[i] as number] as Set<number>) {
      if (prev[v] === -2) { prev[v] = queue[i] as number; queue.push(v); }
    }
  }
  if (prev[t] === -2) return [];
  const path: number[] = [];
  for (let x = t; x !== -1; x = prev[x] as number) path.push(x);
  return path;
}
Correct:
function shortestPath(g: UGraph, s: number, t: number): number[] {
  const prev = new Array<number>(g.n).fill(-2);
  prev[s] = -1;
  const queue = [s];
  for (let i = 0; i < queue.length; i++) {
    for (const v of g.adj[queue[i] as number] as Set<number>) {
      if (prev[v] === -2) { prev[v] = queue[i] as number; queue.push(v); }
    }
  }
  if (prev[t] === -2) return [];
  const path: number[] = [];
  for (let x = t; x !== -1; x = prev[x] as number) path.push(x);
  return path.reverse();
}
Complexity: O(V + E)

