TypeScript · weightedgraph · patterns · L3
Concept: Dijkstra finalizes the unvisited vertex with the smallest distance, not the first one
Misconception: Process vertices in index order and relax their edges.
Explanation: The correctness of Dijkstra rests on one rule: the unfinished vertex with the smallest tentative distance already has its final distance, as long as weights are not negative. Picking any other vertex, such as the lowest index, finalizes distances that a cheaper path would still improve.
Incorrect:
function dijkstraBad(g: WGraph, src: number): number[] {
  const dist = new Array<number>(g.n).fill(Infinity);
  const done = new Array<boolean>(g.n).fill(false);
  dist[src] = 0;
  for (let step = 0; step < g.n; step++) {
    const u = done.indexOf(false);
    done[u] = true;
    for (const [v, w] of g.adj[u] as Edge[]) {
      const nd = (dist[u] as number) + w;
      if (!done[v] && nd < (dist[v] as number)) dist[v] = nd;
    }
  }
  return dist;
}
Correct:
function dijkstra(g: WGraph, src: number): number[] {
  const dist = new Array<number>(g.n).fill(Infinity);
  const done = new Array<boolean>(g.n).fill(false);
  dist[src] = 0;
  for (let step = 0; step < g.n; step++) {
    let u = -1;
    for (let i = 0; i < g.n; i++) {
      if (!done[i] && (u === -1 || (dist[i] as number) < (dist[u] as number))) u = i;
    }
    if (u === -1 || dist[u] === Infinity) break;
    done[u] = true;
    for (const [v, w] of g.adj[u] as Edge[]) {
      if ((dist[u] as number) + w < (dist[v] as number)) dist[v] = (dist[u] as number) + w;
    }
  }
  return dist;
}
Complexity: O(V^2)

