function dijkstra(g: WGraph, src: number): number[] {
  const dist = new Array<number>(g.n).fill(Infinity);
  const done = new Array<boolean>(g.n).fill(false);
  dist[src] = 0;
  for (let step = 0; step < g.n; step++) {
    let u = -1;
    for (let i = 0; i < g.n; i++) {
      if (!done[i] && (u === -1 || (dist[i] as number) < (dist[u] as number))) u = i;
    }
    if (u === -1 || dist[u] === Infinity) break;
    done[u] = true;
    for (const [v, w] of g.adj[u] as Edge[]) {
      if ((dist[u] as number) + w < (dist[v] as number)) dist[v] = (dist[u] as number) + w;
    }
  }
  return dist;
}

