TypeScript · weightedgraph · patterns · L4
Concept: Floyd-Warshall must loop over the intermediate vertex k on the outside
Misconception: The three loops can be nested in any order.
Explanation: The recurrence considers paths that use only the first k vertices as intermediates, so k must be the outermost loop. With k innermost, a cell is combined with cells that are not final yet, and paths that need several intermediates are missed.
Incorrect:
function floydBad(g: WGraph): number[][] {
  const d = Array.from({ length: g.n }, (_, i) =>
    Array.from({ length: g.n }, (_, j) => (i === j ? 0 : Infinity)));
  g.adj.forEach((row, u) => row.forEach(([v, w]) => {
    if (w < ((d[u] as number[])[v] as number)) (d[u] as number[])[v] = w;
  }));
  for (let i = 0; i < g.n; i++) {
    for (let j = 0; j < g.n; j++) {
      for (let k = 0; k < g.n; k++) {
        const via = ((d[i] as number[])[k] as number) + ((d[k] as number[])[j] as number);
        if (via < ((d[i] as number[])[j] as number)) (d[i] as number[])[j] = via;
      }
    }
  }
  return d;
}
Correct:
function floyd(g: WGraph): number[][] {
  const d = Array.from({ length: g.n }, (_, i) =>
    Array.from({ length: g.n }, (_, j) => (i === j ? 0 : Infinity)));
  g.adj.forEach((row, u) => row.forEach(([v, w]) => {
    if (w < ((d[u] as number[])[v] as number)) (d[u] as number[])[v] = w;
  }));
  for (let k = 0; k < g.n; k++) {
    for (let i = 0; i < g.n; i++) {
      for (let j = 0; j < g.n; j++) {
        const via = ((d[i] as number[])[k] as number) + ((d[k] as number[])[j] as number);
        if (via < ((d[i] as number[])[j] as number)) (d[i] as number[])[j] = via;
      }
    }
  }
  return d;
}
Complexity: O(V^3)

