Python B-Trees and B+ Trees · 6. Node layout and search with bisect
6. Node layout and search with bisect
A node is two lists and a flag. Searching a node is one bisect_left: it returns the position of the key if present, or the
index of the child that could contain it. This is the same bisect used for sorted lists, which is why a B-tree node is often
described as a sorted list that has learned to point at children.
import bisect
class BN:
def __init__(self, leaf=True):
self.keys = []                         # sorted
self.kids = []                         # empty for a leaf, else len(keys) + 1
self.leaf = leaf
class BTree:
def __init__(self, t=2):
self.t = t                             # minimum degree: 2t - 1 keys is the maximum
self.root = BN()
def search(self, k, n=None):
n = n or self.root
i = bisect.bisect_left(n.keys, k)
if i < len(n.keys) and n.keys[i] == k:
return True
return False if n.leaf else self.search(k, n.kids[i])
def inorder(self, n=None):
n = n or self.root
if n.leaf:
return list(n.keys)
out = []
for i, k in enumerate(n.keys):
out += self.inorder(n.kids[i]) + [k]
return out + self.inorder(n.kids[-1])
def height(self):
h, n = 1, self.root
while not n.leaf:
n = n.kids[0]
h += 1
return h
demo = BTree(2)
demo.root.keys = [10, 20]
demo.root.leaf = False
demo.root.kids = [BN(), BN(), BN()]
demo.root.kids[0].keys = [5, 6, 7]
demo.root.kids[1].keys = [12, 17]
demo.root.kids[2].keys = [30]
assert demo.search(17) and demo.search(10) and not demo.search(13)
assert demo.inorder() == [5, 6, 7, 10, 12, 17, 20, 30] and demo.height() == 2

