Python B-Trees and B+ Trees · 11. B+ tree insert, get and range scan
11. B+ tree insert, get and range scan
The node classes are small. A leaf holds keys, values and a pointer to the next leaf; an inner node holds separators
and children. Insert returns None when nothing split, or a pair (separator, new right node) that the caller inserts into
its own lists. The same contract is the recursion contract from the binary tree blueprint: say what each call returns.
class Leaf:
def __init__(self):
self.keys, self.vals, self.next = [], [], None
class Inner:
def __init__(self):
self.keys, self.kids = [], []
class BPlus:
def __init__(self, order=4):
self.m = order                         # a node splits when it reaches m keys
self.root = Leaf()
def _leaf(self, k):
n = self.root
while isinstance(n, Inner):
n = n.kids[bisect.bisect_right(n.keys, k)]   # equal goes right
return n
def get(self, k):
leaf = self._leaf(k)
i = bisect.bisect_left(leaf.keys, k)
return leaf.vals[i] if i < len(leaf.keys) and leaf.keys[i] == k else None
def insert(self, k, v):
res = self._ins(self.root, k, v)
if res:                                # the root split: grow by one level
sep, right = res
r = Inner()
r.keys, r.kids = [sep], [self.root, right]
self.root = r
The recursive helper does the real work: a leaf split copies the separator up; an inner split moves it up.
def _ins(self, n, k, v):
if isinstance(n, Leaf):
i = bisect.bisect_left(n.keys, k)
if i < len(n.keys) and n.keys[i] == k:
n.vals[i] = v                  # existing key: update
return None
n.keys.insert(i, k)
n.vals.insert(i, v)
if len(n.keys) < self.m:
return None
mid = len(n.keys) // 2
r = Leaf()
r.keys, r.vals = n.keys[mid:], n.vals[mid:]
n.keys, n.vals = n.keys[:mid], n.vals[:mid]

Python Binary Search Trees · 8. Order queries: kth, floor, ceiling, successor, range
8. Order queries: kth, floor, ceiling, successor, range
The reason to use a BST at all is order. Each query below prunes a subtree at every step, so it costs O(h), except the
range query, which costs O(h + k) for k results.
def kth(r, k):                                 # 1-based, iterative inorder
st = []
while st or r:
while r:
st.append(r)
r = r.left
r = st.pop()
k -= 1
if k == 0:
return r.val
r = r.right
return None
def floor(r, x):                               # largest key <= x
best = None
while r:
if r.val == x:
return r.val
if r.val < x:
best = r.val
r = r.right
else:
r = r.left
return best
def succ(r, x):                                # smallest key > x
best = None
while r:
if x < r.val:
best = r.val
r = r.left
else:
r = r.right
return best
def rng(r, lo, hi):                            # sum of keys in [lo, hi]
if r is None:
return 0
if r.val < lo:
return rng(r.right, lo, hi)
if r.val > hi:
return rng(r.left, lo, hi)
return r.val + rng(r.left, lo, hi) + rng(r.right, lo, hi)
assert kth(T, 3) == 4 and kth(T, 99) is None
assert floor(T, 6) == 5 and floor(build([5, 3, 8]), 2) is None
assert succ(T, 5) == 7 and succ(T, 9) is None and succ(build([5, 3, 8]), 4) == 5
assert rng(build([10, 5, 15, 3, 7, 18]), 7, 15) == 32
