go(start)
return order
Correct:
def dfs(adj, start):
seen, order, stack = {start}, [], [start]
while stack:
u = stack.pop()
order.append(u)
for v in adj[u]:
if v not in seen:
seen.add(v)
stack.append(v)
return order
