def search_rotated(a, x):
lo, hi = 0, len(a) - 1
while lo <= hi:
mid = (lo + hi) // 2
if a[mid] == x:
return mid
if a[lo] <= a[mid]:  # left half sorted
if a[lo] <= x < a[mid]:
hi = mid - 1
else:
lo = mid + 1
else:  # right half sorted
