class Graph
def initialize(directed: false)
@directed = directed
@adj = {}
end
def add_vertex(v)
@adj[v] ||= []
self
end
def add_edge(u, v)
add_vertex(u)
add_vertex(v)
@adj[u] << v
@adj[v] << u unless @directed
self
end
def neighbors(v)
@adj.fetch(v, [])
end
def vertices
@adj.keys
end
end
