class RingDeque
include Enumerable
attr_reader :size
def initialize(cap = 4)
@buf = Array.new(cap)
@head = 0
@size = 0
end
def capacity
@buf.size
end
def full?
@size == @buf.size
end
def empty?
@size.zero?
end
def push_back(v)
return false if full?
@buf[(@head + @size) % @buf.size] = v
@size += 1
end
def push_front(v)
return false if full?
@head = (@head - 1) % @buf.size
@buf[@head] = v
@size += 1
end
def pop_front
return nil if empty?
v = @buf[@head]
@buf[@head] = nil
@head = (@head + 1) % @buf.size
@size -= 1
v
end
def pop_back
return nil if empty?
i = (@head + @size - 1) % @buf.size
v = @buf[i]
@buf[i] = nil
@size -= 1
v
end
def front
empty? ? nil : @buf[@head]
end
def back
empty? ? nil : @buf[(@head + @size - 1) % @buf.size]
end
def each
return to_enum(:each) unless block_given?
@size.times { |i| yield @buf[(@head + i) % @buf.size] }
end
end
