end
Correct:
def bfs(graph, start)
order = []
seen = { start => true }
queue = [start]
until queue.empty?
node = queue.shift
order << node
graph[node].each do |n|
next if seen[n]
seen[n] = true
queue.push(n)
end
end
order
end
