function edgeCountBad(g: UGraph): number {
let sum = 0;
for (const s of g.adj) sum += s.size;
return sum / 2;
}
Correct:
function edgeCount(g: UGraph): number {
let sum = 0;
let loops = 0;
g.adj.forEach((s, u) => {
sum += s.size;
if (s.has(u)) loops++;
});
return (sum + loops) / 2;
}

